{
  "name": "滨松 H11890 光子计数头",
  "name_en": "Hamamatsu H11890 Photon Counting Head",
  "manufacturer": "Hamamatsu Photonics",
  "description": "H11890 是一类用于弱光检测的光子计数头，通常集成光电探测器、高压偏置与计数电子学，可对入射光产生的脉冲进行计数。它适用于荧光、发光、散射及其他低光强实验中的光子计数测量。",
  "description_en": "The H11890 is a photon counting head for low-light measurements, typically integrating a photodetector, high-voltage bias supply, and counting electronics to count pulses generated by incident light. It is used for photon counting in fluorescence, luminescence, scattering, and other low-intensity optical experiments.",
  "tag_hints": [
    "photon counting",
    "low-light detection",
    "Hamamatsu",
    "photomultiplier detector",
    "high-voltage bias",
    "optical measurements",
    "fluorescence detection"
  ],
  "actions": [
    {
      "action_name": "auto-doInitializeDevice",
      "description": "初始化光子计数头。",
      "description_en": "Initialize the photon counting head."
    },
    {
      "action_name": "auto-doShutdownDevice",
      "description": "关闭并停用光子计数头。",
      "description_en": "Shut down and deactivate the photon counting head."
    },
    {
      "action_name": "auto-sendCommand",
      "description": "向设备发送底层控制命令。",
      "description_en": "Send a low-level control command to the device."
    },
    {
      "action_name": "auto-readReply",
      "description": "读取设备返回的数据或状态应答。",
      "description_en": "Read the device reply or status response."
    },
    {
      "action_name": "auto-get_integration_time",
      "description": "获取计数积分时间。",
      "description_en": "Get the counting integration time."
    },
    {
      "action_name": "auto-set_integration_time",
      "description": "设置计数积分时间。",
      "description_en": "Set the counting integration time."
    },
    {
      "action_name": "auto-get_repetition",
      "description": "获取重复计数次数。",
      "description_en": "Get the number of repeated counting cycles."
    },
    {
      "action_name": "auto-set_repetition",
      "description": "设置重复计数次数。",
      "description_en": "Set the number of repeated counting cycles."
    },
    {
      "action_name": "auto-turn_on",
      "description": "打开光子计数头。",
      "description_en": "Turn on the photon counting head."
    },
    {
      "action_name": "auto-turn_off",
      "description": "关闭光子计数头。",
      "description_en": "Turn off the photon counting head."
    },
    {
      "action_name": "auto-get_high_voltage",
      "description": "获取探测器高压设置。",
      "description_en": "Get the detector high-voltage setting."
    },
    {
      "action_name": "auto-set_high_voltage",
      "description": "设置探测器高压。",
      "description_en": "Set the detector high voltage."
    },
    {
      "action_name": "auto-start_counting",
      "description": "开始进行光子计数采集。",
      "description_en": "Start photon counting acquisition."
    },
    {
      "action_name": "auto-fetchAll",
      "description": "读取全部已采集的计数结果。",
      "description_en": "Fetch all acquired counting results."
    },
    {
      "action_name": "auto-fetchOne",
      "description": "读取一组计数结果。",
      "description_en": "Fetch one counting result."
    },
    {
      "action_name": "auto-stop_counting",
      "description": "停止光子计数采集。",
      "description_en": "Stop photon counting acquisition."
    }
  ]
}

